infra.infra/prod/main.tf:
terraform {
  backend "s3" {}
}
provider "aws" {
  allowed_account_ids = ["111111111111"]
}
provider "aws" {
  alias               = "other"
  allowed_account_ids = ["222222222222"]
}
resource "aws_iam_role" "r" {
  name               = "worker"
  assume_role_policy = "{}"
}
resource "aws_iam_role_policy" "p" {
  provider = aws.other
  role     = "worker"
  policy   = jsonencode({ Statement = [{ Effect = "Allow", Action = "secretsmanager:GetSecretValue", Resource = "*" }] })
}

